SELECT [Gesamt Normierung Zeitraum].Elektrolyseur, [Gesamt Normierung Zeitraum].Position, qryCEAlleElemente.Bezeichnung, [Gesamt Normierung Zeitraum].Datum, [Gesamt Normierung Zeitraum].i, SPCBer([Gesamt Normierung Zeitraum]![Un],[qryCEAlleElemente]![µNaOH]) AS Energieverbrauch, [Gesamt Normierung Zeitraum].Un, qryCEAlleElemente.µNaOH AS CE, GetGewIRef() AS iRefSPC
FROM [Gesamt Normierung Zeitraum] INNER JOIN qryCEAlleElemente ON ([Gesamt Normierung Zeitraum].Position = qryCEAlleElemente.Position) AND ([Gesamt Normierung Zeitraum].Datum = qryCEAlleElemente.Datum) AND ([Gesamt Normierung Zeitraum].Elektrolyseur = qryCEAlleElemente.Elektrolyseur);
